// Gemini response structure:
// { candidates: [ { content: { parts: [ { text: "extracted question" } ] } } ] }

const geminiResponse = $input.first().json;

// Extract the text Gemini returned
const extractedQuestion = geminiResponse.candidates[0].content.parts[0].text.trim();

// Get sessionId and language from the original Code in JavaScript node
const originalData = $('Code in JavaScript').first().json;

// Pass forward in the SAME format as text-only messages
// so Router Agent works without any changes
return [{
  json: {
    sessionId:       originalData.sessionId,
    chatInput:       extractedQuestion,
    originalMessage: extractedQuestion,
    cleanedMessage:  extractedQuestion,
    timestamp:       new Date().toISOString(),
    language:        originalData.language || "english",
    isMeaningful:    true,
    hasImage:        true,
    metadata:        originalData.metadata
  }
}];

