const instructionMap = {

  ask_question: `The student wants an explanation.
Explain the concept clearly in 3-4 steps.
State the formula first, explain each variable, 
then show one brief example.
Do NOT solve the student's specific numbers — 
explain the concept only.`,

  solve_problem: `The student wants this problem fully solved.
IMPORTANT: Solve the ACTUAL numbers given by the student.
Use the available calculation tools to get the exact answer.
Show EVERY step of working:
Step 1: Write the formula
Step 2: Substitute the values  
Step 3: Calculate and show working
Step 4: State the final answer clearly
For bearing problems: find interior angle FIRST before calculating.
`,

  worked_example: `The student wants a fully worked solution.
Use the available calculation tools to get the exact answer.
Show EVERY step of working, numbered Step 1, Step 2, Step 3...
After showing the answer, explain WHY each step was done.`,

  need_hint: `The student needs a hint, not a full solution.
Give ONE small clue only — do not solve the problem.
Ask the student what they think the next step is.`,

  topic_explain: `The student wants a concept overview.
Give a clear definition first.
Then explain when this concept appears in SPM questions.
List the formula(s) with every variable name explained.`,

  off_topic: `This question is outside the topic.
Politely redirect the student back to 
Chapter 9 Solution of Triangles.`
};

// ─────────────────────────────────
// KEYWORD DETECTOR
// Detects if message needs solving
// even if Router Agent classifies wrong
// ─────────────────────────────────
const message = (
  $json.cleanedMessage || 
  $json.chatInput || 
  ""
).toLowerCase();

const hasBearing = message.includes("bearing");

const hasNumbers = /\d/.test(message);

const hasCalculateWord = 
  message.includes("calculate") ||
  message.includes("find") ||
  message.includes("cari") ||
  message.includes("hitung") ||
  message.includes("distance") ||
  message.includes("jarak") ||
  message.includes("estimate") ||
  message.includes("anggar") ||
  message.includes("how far") ||
  message.includes("how long") ||
  message.includes("berapa");

// ─────────────────────────────────
// INTENT DECISION
// ─────────────────────────────────
let intent = $json.intent || "ask_question";

if (hasBearing && hasNumbers) {
  // Bearing + numbers = definitely solve
  intent = "solve_problem";

} else if (hasNumbers && hasCalculateWord) {
  // Numbers + calculate word = solve
  intent = "solve_problem";

} else {
  // Otherwise trust the Router Agent
  if (instructionMap[intent]) {
    intent = intent;
  } else {
    intent = "ask_question";
  }
}

const teachingInstruction = 
  instructionMap[intent] || 
  instructionMap["ask_question"];

return [{
  json: {
    ...$json,
    intent: intent,
    teachingInstruction: teachingInstruction
  }
}];

// ── Strip LaTeX notation ──────────────────
function stripLatex(text) {
  if (!text) return text;
  return text
    .replace(/\$\$[\s\S]*?\$\$/g, match => 
      match.replace(/\$\$/g, '').trim())
    .replace(/\$([^$\n]+)\$/g, '$1')
    .replace(/\\text\{([^}]+)\}/g, '$1')
    .replace(/\\frac\{([^}]+)\}\{([^}]+)\}/g, '$1/$2')
    .replace(/\^\\circ/g, '°')
    .replace(/\\circ/g, '°')
    .replace(/\\times/g, '×')
    .replace(/\\approx/g, '≈')
    .replace(/\\tan/g, 'tan')
    .replace(/\\sin/g, 'sin')
    .replace(/\\cos/g, 'cos')
    .replace(/\\sqrt\{([^}]+)\}/g, '√($1)')
    .replace(/\\left/g, '')
    .replace(/\\right/g, '')
    .replace(/\\\[/g, '')
    .replace(/\\\]/g, '')
    .replace(/\\\(/g, '')
    .replace(/\\\)/g, '')
    .replace(/\\/g, '')
    .replace(/\{|\}/g, '')
    .trim();
}

const agentResponse = stripLatex(
  $json.output || $json.text || ""
);

const intent   = $json.intent   || "ask_question";
const language = $json.language || "english";
const isMalay  = language === "malay";

const headerMap = {
  ask_question:   isMalay ? "📘 Penjelasan:"   : "📘 Explanation:",
  solve_problem:  isMalay ? "✏️ Penyelesaian:" : "✏️ Solution:",
  worked_example: isMalay ? "✏️ Penyelesaian Langkah demi Langkah:" 
                           : "✏️ Step-by-Step Solution:",
  topic_explain:  isMalay ? "📖 Gambaran Konsep:" 
                           : "📖 Concept Overview:",
  need_hint:      isMalay ? "💡 Petunjuk:" : "💡 Hint:",
  off_topic:      ""
};

const header = headerMap[intent] || "";
const formattedResponse = header
  ? `${header}\n\n${agentResponse}`
  : agentResponse;

return [{
  json: {
    ...$json,
    output: formattedResponse
  }
}];

// ═══════════════════════════════════════════════════
// PARSE INTENT CODE NODE  — v2
// 
// PURPOSE:
// 1. Extract the intent label from Router Agent output
// 2. Apply keyword safety net for solve_problem
// 3. Validate and fallback gracefully
// ═══════════════════════════════════════════════════


// ── STEP 1: Get the raw Router Agent output ──────────
const rawOutput = (
  $json.output || $json.text || ""
).toLowerCase().trim();


// ── STEP 2: Clean to letters and underscores only ────
// This removes punctuation, spaces, newlines, numbers
// so "ask_question." → "ask_question"
const cleaned = rawOutput.replace(/[^a-z_]/g, "");


// ── STEP 3: All valid intents (MUST match Switch node) 
// solve_problem is INCLUDED — this was the missing label
const validIntents = [
  "solve_problem",    // ← ADDED: numbers + calculation
  "ask_question",     // how something works / explanation
  "need_hint",        // student is stuck / needs clue
  "worked_example",   // show me a full solved example
  "topic_explain",    // what is X / define X
  "off_topic"         // unrelated to Additional Maths
];


// ── STEP 4: Try to match Router Agent label exactly ──
// We check for exact label match first (preferred)
// Then fall back to substring match (less strict)
let intent = null;

// EXACT MATCH: cleaned output IS one of the labels
for (const candidate of validIntents) {
  if (cleaned === candidate) {
    intent = candidate;
    break;
  }
}

// SUBSTRING MATCH: label appears inside a longer output
// e.g. LLM said "the label is ask_question" instead of
// just "ask_question"
if (!intent) {
  for (const candidate of validIntents) {
    if (cleaned.includes(candidate)) {
      intent = candidate;
      break;
    }
  }
}


// ── STEP 5: Keyword safety net for solve_problem ─────
// If Router Agent misclassified but message clearly
// contains numbers + action word → override to solve
const message = (
  $json.cleanedMessage ||
  $json.chatInput ||
  ""
).toLowerCase();

const hasNumbers = /\d/.test(message);

const hasBearing = message.includes("bearing");

const hasCalculateWord =
  message.includes("calculate") ||
  message.includes("find") ||
  message.includes("cari") ||
  message.includes("hitung") ||
  message.includes("selesaikan") ||
  message.includes("solve") ||
  message.includes("distance") ||
  message.includes("jarak") ||
  message.includes("estimate") ||
  message.includes("anggar") ||
  message.includes("how far") ||
  message.includes("how long") ||
  message.includes("berapa") ||
  message.includes("luas") ||
  message.includes("buktikan") ||
  message.includes("tunjukkan") ||
  message.includes("work out") ||
  message.includes("kirakan");

// Override: bearing + numbers always = solve_problem
if (hasBearing && hasNumbers) {
  intent = "solve_problem";

// Override: numbers + action word = solve_problem
// BUT only if Router Agent didn't clearly say need_hint
// or worked_example (respect those classifications)
} else if (
  hasNumbers &&
  hasCalculateWord &&
  intent !== "need_hint" &&
  intent !== "worked_example" &&
  intent !== "off_topic"
) {
  intent = "solve_problem";
}


// ── STEP 6: Final fallback ───────────────────────────
// If nothing matched at all, default to ask_question
if (!intent) {
  intent = "ask_question";
}


// ── STEP 7: Return with full context preserved ───────
return [{
  json: {
    ...$json,
    intent,
    routedAt: new Date().toISOString(),

    // Debug fields — helps you trace issues in Executions
    _debug: {
      rawRouterOutput: rawOutput,
      cleanedOutput:   cleaned,
      resolvedBy:      cleaned === intent
                         ? "exact_match"
                         : hasNumbers && hasCalculateWord
                           ? "keyword_override"
                           : "substring_match"
    }
  }
}];

// Webhook sends: body.chatInput, body.sessionId
// + NEW: body.hasImage, body.image, body.imageType
const rawMessage = $json.body?.chatInput || $json.body?.message || $json.chatInput || $json.message || "";
const sessionId  = $json.body?.sessionId || $json.sessionId || "default";

// ── NEW: read image fields from webhook body ──
const hasImage  = $json.body?.hasImage  === true && !!$json.body?.image;
const image     = hasImage ? $json.body.image     : null;
const imageType = hasImage ? $json.body.imageType : null;

const cleanedMessage = rawMessage.trim();

const malayKeywords = /\b(cari|hitung|tunjuk|buktikan|diberi|segi|tiga|sudut|panjang|luas|nilai|apakah|petua|kosinus)\b/i;
const language = malayKeywords.test(rawMessage) ? "malay" : "english";

// ── UPDATED: meaningful if has text OR has image ──
const isMeaningful = cleanedMessage.length > 3 || hasImage;

return [{
  json: {
    sessionId,
    chatInput:       cleanedMessage,
    originalMessage: rawMessage,
    cleanedMessage,
    timestamp:       new Date().toISOString(),
    language,
    isMeaningful,
    // ── NEW image fields ──
    hasImage,
    image,
    imageType,
    metadata: {
      source:  "webhook",
      subject: "additional_mathematics",
      topic:   "solution_of_triangles",
      syllabus: "KSSM_Form4"
    }
  }
}];
